      const newEmpId = `emp_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
      const qrToken = `emp_${Math.random().toString(36).slice(2, 10)}${Math.random().toString(36).slice(2, 10)}`;
      const { error } = await supabase.from("employees").insert({
        id: newEmpId, owner_id: userData.user.id, shop_id: activeShopId,
        name: empName.trim(), role: empRole, permissions, pin_hash: pinHash, active: true, qr_token: qrToken,
        shift_schedule: empShiftSchedule,
      });
      if (error) { setEmpError(error.message); return; }
      const newEmp = { id: newEmpId, name: empName.trim(), role: empRole, permissions, pinHash, active: true, createdAt: new Date().toISOString(), qrToken, shiftSchedule: empShiftSchedule };
      setEmployees([...employees, newEmp]);
