    const productLimit = !active ? FREE_PRODUCT_LIMIT : (currentPlan === "pro" ? PRO_PRODUCT_LIMIT : null);
    if (productLimit !== null && products.length >= productLimit) {
      setError(t(lang, "productLimitReached").replace("{n}", productLimit));
      return;
    }
    setError("");
